  push: {}

steps.run:
rc=0
pantheon-skill-auditor validate structure --allow-dirs=evals skills/adr-creator || rc=$?
case "$rc" in
  0) ;;
  2) echo "::warning::validate structure reported warnings only" ;;
  *) exit "$rc" ;;
esac

grade=$(pantheon-skill-auditor evaluate ./skills/adr-creator --json | jq -r '.grade // "?"')
echo "grade: $grade"
case "$grade" in
  A|A+) ;;
  B+|B) echo "::warning::skill grade $grade is below A" ;;
  *) echo "::error::skill grade $grade is below B"; exit 1 ;;
esac

